gre(){return"\u0420\u0435\u0448\u0438\u0442\u044c \u043f\u043e\u0437\u0436\u0435 (\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439/\u0441\u0442\u0438\u043b\u043e\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0430\u043d\u0430\u043b\u0438\u0437 \u0431\u0435\u0437 \u043c\u043e\u0434\u0435\u043b\u0438)"},
grf(){return"\u0412\u044b \u0432\u0441\u0435\u0433\u0434\u0430 \u043c\u043e\u0436\u0435\u0442\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u043c\u043e\u0434\u0435\u043b\u044c \u043f\u043e\u0437\u0436\u0435 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \xab\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u2192 \u0423\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043c\u043e\u0434\u0435\u043b\u044f\u043c\u0438 \u0418\u0418\xbb; \u0432\u0430\u043c \u043d\u0430\u043f\u043e\u043c\u043d\u044f\u0442 \u0441\u043d\u043e\u0432\u0430 \u043f\u0440\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0438 \u0430\u043d\u0430\u043b\u0438\u0437\u0430, \u0442\u0440\u0435\u0431\u0443\u044e\u0449\u0435\u0433\u043e \u043c\u043e\u0434\u0435\u043b\u044c."},
gqO(){return"\u0418\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c:"},
gm1(){return"\u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f"},
gqW(){return"\u0420\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u0442\u0441\u044f"},
gqN(){return"\u041f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0430\u044f"},
qX(a,b,c,d){return a+" \xb7 "+b+" \xb7 \u0422\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f "+c+" \u0413\u0411 \u041e\u0417\u0423 \xb7 v"+d},
qY(a,b,c){return"\u0420\u0430\u0437\u043c\u0435\u0440: "+a+" \xb7 \u0422\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0442\u043e\u0440: "+b+" \xb7 \u0418\u043d\u0434\u0435\u043a\u0441 \u043c\u0435\u0442\u043a\u0438 \u0418\u0418: "+c},
qS(a,b,c){return"\u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0430\u2026 "+a+"% ("+b+" / "+c+")"},
qR(a){return"\u0417\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c ("+a+")"},
gqM(){return"\u0421\u043a\u043e\u0440\u043e"},
gm4(){return"\u0421\u0434\u0435\u043b\u0430\u0442\u044c \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0439"},
gqZ(){return"\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c"},
